-- BookKG complete schema. Run in Supabase SQL Editor.
create table if not exists public.stores(id bigint generated by default as identity primary key,name text not null,address text,whatsapp text,active boolean not null default true,created_at timestamptz default now());
create table if not exists public.books(id bigint generated by default as identity primary key,isbn text unique,title text not null,author text,created_at timestamptz default now());
create table if not exists public.store_offers(id bigint generated by default as identity primary key,store_id bigint not null references public.stores(id) on delete cascade,book_id bigint not null references public.books(id) on delete cascade,price numeric(12,2),available boolean not null default false,updated_at timestamptz default now(),unique(store_id,book_id));
create table if not exists public.user_profiles(id uuid primary key references auth.users(id) on delete cascade,role text not null default 'store' check(role in ('admin','store')),store_id bigint references public.stores(id) on delete set null);
create table if not exists public.store_applications(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,store_name text not null,address text,whatsapp text,phone text,status text not null default 'pending' check(status in ('pending','approved','rejected')),created_at timestamptz default now());
alter table public.stores enable row level security;alter table public.books enable row level security;alter table public.store_offers enable row level security;alter table public.user_profiles enable row level security;alter table public.store_applications enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_profiles where id=auth.uid() and role='admin'); $$;
drop policy if exists "Public read active stores" on public.stores;create policy "Public read active stores" on public.stores for select using(active=true or public.is_admin());
drop policy if exists "Admin manage stores" on public.stores;create policy "Admin manage stores" on public.stores for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists "Public read books" on public.books;create policy "Public read books" on public.books for select using(true);
drop policy if exists "Admin manage books" on public.books;create policy "Admin manage books" on public.books for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists "Public read offers" on public.store_offers;create policy "Public read offers" on public.store_offers for select using(true);
drop policy if exists "Admin manage offers" on public.store_offers;create policy "Admin manage offers" on public.store_offers for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists "Own profile read" on public.user_profiles;create policy "Own profile read" on public.user_profiles for select using(id=auth.uid() or public.is_admin());
drop policy if exists "Admin manage profiles" on public.user_profiles;create policy "Admin manage profiles" on public.user_profiles for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists "Submit own application" on public.store_applications;create policy "Submit own application" on public.store_applications for insert to authenticated with check(user_id=auth.uid());
drop policy if exists "Read own application or admin" on public.store_applications;create policy "Read own application or admin" on public.store_applications for select to authenticated using(user_id=auth.uid() or public.is_admin());
drop policy if exists "Admin update applications" on public.store_applications;create policy "Admin update applications" on public.store_applications for update to authenticated using(public.is_admin()) with check(public.is_admin());
-- Store accounts can only read/update their own offers and create book records needed for their own inventory.
drop policy if exists "Store manage own offers" on public.store_offers;
create policy "Store manage own offers" on public.store_offers for all to authenticated using(public.is_admin() or exists(select 1 from public.user_profiles p where p.id=auth.uid() and p.role='store' and p.store_id=store_id)) with check(public.is_admin() or exists(select 1 from public.user_profiles p where p.id=auth.uid() and p.role='store' and p.store_id=store_id));
drop policy if exists "Store insert books" on public.books;
create policy "Store insert books" on public.books for insert to authenticated with check(exists(select 1 from public.user_profiles where id=auth.uid() and role in ('admin','store')));
grant select on public.stores,public.books,public.store_offers to anon,authenticated;grant insert,update,delete on public.stores,public.books,public.store_offers to authenticated;grant select,insert,update on public.user_profiles,public.store_applications to authenticated;
